-- Step 4 of the Nightbane extraction plan: the vehicles, printed 231-232. 35 rows.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzzzzzzzzz-nb-vehicles.sql
--
-- D4 (#1126): vehicles are in scope and are `nightbane` rows of their own. Shaped
-- exactly as add-hu-vehicles.sql shaped Heroes Unlimited's: vehicle_class `vehicle`;
-- the S.D.C. in mdc_main_body with is_mega_damage = 0 (migration 062); A.R. in `ar`;
-- the speed in the column for the regime - airplanes speed_air, underwater vehicles
-- speed_water, the rest speed_ground. All 35 rows were compared with HU's rows for
-- the same entries and agree on every value column; Nightbane prints none of HU's
-- military vehicles or helicopters. The book prints no price for the airplanes or
-- the underwater vehicles, so `cost` is NULL there.


-- Read the result back. This batch asserts its OWN rows and nothing else.
SELECT 'all 35 vehicles are in, as nightbane S.D.C. vehicles' AS assertion, count(*) AS got, 35 AS want
  FROM vehicles WHERE system = 'nightbane' AND is_mega_damage = 0 AND source_book LIKE 'Nightbane RPG p.%'
   AND slug IN ('compact-nb', 'mid-size-nb', 'full-size-sedan-nb', 'luxury-sedan-nb', 'sports-car-nb', 'corvette-nb', 'mini-van-nb', 'full-size-van-nb', 'jeep-4-wheel-drive-nb', 'small-truck-4-wheel-drive-nb', 'small-truck-nb', '16ft-truck-u-haul-type-nb', '24ft-truck-u-haul-type-nb', 'semi-truck-cab-only-nb', 'bmw-sedan-nb', 'bmw-sports-car-nb', 'delorean-nb', 'jaguar-nb', 'lamborghini-countach-nb', 'mercedes-benz-sedan-nb', 'mercedes-benz-sports-car-nb', 'porsche-nb', 'rolls-royce-luxury-sedan-nb', 'volvo-sedan-nb', 'motorcycle-light-nb', 'motorcycle-medium-nb', 'motorcycle-heavy-nb', 'single-engine-nb', 'twin-engine-nb', 'small-jet-nb', 's-c-u-b-a-scooter-nb', 's-c-u-b-a-scooter-platform-nb', 'sea-sled-cav-nb', 'waterdinger-nb', 'two-diver-submersible-transport-vehicle-nb');

-- Records this run. See db/migrations/024-data-script-runs.sql.
